import type { Modality } from '@/api/types';
import type { ModalityFormConfig, ModalityFormProps } from './types';
import { LocationForm, locationDefaultData, validateLocationData } from './LocationForm';
import { WeatherForm, weatherDefaultData, validateWeatherData, transformWeatherData } from './WeatherForm';
import { EmailForm, emailDefaultData, validateEmailData, transformEmailData } from './EmailForm';

// Form components
export { LocationForm, locationDefaultData, validateLocationData } from './LocationForm';
export { WeatherForm, weatherDefaultData, validateWeatherData, transformWeatherData } from './WeatherForm';
export { EmailForm, emailDefaultData, validateEmailData, transformEmailData } from './EmailForm';

case 'email': {
  const op = data.operation as string;
  const subject = data.subject as string | undefined;
  const from = data.from_address as string | undefined;
  const to = data.to_addresses as string | undefined;
  const msgId = data.message_id as string | undefined;

  switch (op) {
    case 'receive':
      return subject ? `Receive: "${subject}" from ${from}` : `Receive email from ${from}`;
    case 'send':
      return subject ? `Send: "${subject}" to ${to}` : `Send email to ${to}`;
    case 'reply':
    case 'reply_all':
      return subject ? `Reply: "${subject}"` : `Reply to message`;
    case 'mark_read':
      return `Mark as read: ${msgId || 'message'}`;
    case 'mark_unread':
      return `Mark as unread: ${msgId || 'message'}`;
    case 'delete':
      return `Delete: ${msgId || 'message'}`;
    case 'archive':
      return `Archive: ${msgId || 'message'}`;
    case 'star':
      return `Star: ${msgId || 'message'}`;
    case 'unstar':
      return `Unstar: ${msgId || 'message'}`;
    case 'move':
      return `Move ${msgId || 'message'} to ${data.target_folder || 'folder'}`;
    default:
      return `Email operation: ${op}`;
  }
}

