                {loc.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <p className="text-xs text-muted-foreground">
          Affects number formatting, month/day names
        </p>
      </div>

      {/* Week Start */}
      <div className="space-y-2">
        <Label htmlFor="week_start">Week Starts On</Label>
        <Select
          value={(data.week_start as string) || ''}
