              placeholder="group_abc123..."
              value={data.group_id as string}
              onChange={(e) => handleChange('group_id', e.target.value)}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="phone_number">Your Phone Number</Label>
            <Input
              id="phone_number"
              placeholder="+15551234567"
