/**
 * Main application component with routing configuration.
 */
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Layout } from '@/components/layout';
import { Dashboard, EventManager, ModalityPage } from '@/pages';
import { TimelineDemo } from '@/pages/TimelineDemo';
import { Toaster } from '@/components/ui/sonner';

// Create a client
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000,
      retry: 1,
    },
  },
});

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <BrowserRouter>
        <Routes>
          <Route path="/" element={<Layout />}>
            <Route index element={<Dashboard />} />
            <Route path="events" element={<EventManager />} />
            <Route path="modalities/:modality" element={<ModalityPage />} />
          </Route>
          {/* Demo pages (outside main layout) */}
          <Route path="/demo/timeline" element={<TimelineDemo />} />
        </Routes>
      </BrowserRouter>
      <Toaster position="bottom-right" />
    </QueryClientProvider>
  );
}

/**
 * Event components exports.
 */

// Main components
export { EventCreationDialog } from './EventCreationDialog';
export { EventTimeline } from './EventTimeline';

// Form components

