/**
 * Filter state type.
 */
interface FilterState {
  modalities: Set<Modality>;
  statuses: Set<string>;
}

/**
 * All available modalities for filtering.
 */
const ALL_MODALITIES: Modality[] = ['location', 'weather', 'time', 'email', 'sms', 'chat', 'calendar'];

/**
 * All available statuses for filtering.
 */
const ALL_STATUSES = ['pending', 'executed', 'cancelled', 'failed'];

/**
 * Calculate spacing between two events based on time difference.
 */
function calculateSpacing(
  time1: Date, 
  time2: Date, 
  zoom: number
): number {
  const diffMinutes = Math.abs(differenceInMinutes(time2, time1));
  const rawSpacing = diffMinutes * ZOOM_CONFIG.pixelsPerMinute * zoom;

  // Clamp spacing between min and max
  return Math.max(
    ZOOM_CONFIG.minSpacing, 
    Math.min(rawSpacing, ZOOM_CONFIG.maxSpacing * zoom)
  );
}

/**
 * Get time gap indicator style based on duration.
 */
function getTimeGapStyle(minutes: number): { 
  show: boolean; 
  label: string | null; 
  height: number;
  dashed: boolean;
} {
  if (minutes < TIME_GAP_THRESHOLDS.medium) {
    return { show: false, label: null, height: 0, dashed: false };
  }
  if (minutes < TIME_GAP_THRESHOLDS.large) {
    return { show: true, label: null, height: 20, dashed: true };
  }
  if (minutes < TIME_GAP_THRESHOLDS.veryLarge) {
    const hours = Math.floor(minutes / 60);
    return { show: true, label: `${hours}h gap`, height: 30, dashed: true };
  }
  // Very large gap
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);
  const label = days > 0 ? `${days}d ${hours % 24}h` : `${hours}h`;
  return { show: true, label: `${label} gap`, height: 40, dashed: true };
}

