      {/* Line */}
      <div className="h-0.5 w-4 bg-primary" />

      {/* Right label */}
      <div className="w-[calc(50%-24px)] pl-4 text-left">
        <span className="text-xs text-muted-foreground">
          {formattedDate} {formattedTime}
        </span>
      </div>
    </div>
  );
}

/**
 * Event Timeline component.
 */
export function EventTimeline({ events, currentTime, onEventClick }: EventTimelineProps) {
  // Sort events by scheduled time and assign sides
  const sortedEvents = useMemo(() => {
    const sorted = [...events].sort(
      (a, b) => new Date(a.scheduled_time).getTime() - new Date(b.scheduled_time).getTime()
    );

    // Assign alternating sides
    return sorted.map((event, index) => ({
      event,
      side: (index % 2 === 0 ? 'left' : 'right') as 'left' | 'right',
    }));
  }, [events]);

  // Find where to insert the current time marker
  const currentTimePosition = useMemo(() => {
    if (!currentTime) return -1;
    const currentMs = new Date(currentTime).getTime();

    for (let i = 0; i < sortedEvents.length; i++) {
      const eventMs = new Date(sortedEvents[i].event.scheduled_time).getTime();
      if (currentMs < eventMs) {
        return i;
      }
    }
    return sortedEvents.length;
  }, [sortedEvents, currentTime]);

  if (events.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-muted-foreground">
        <Calendar className="h-12 w-12 mb-4 opacity-50" />
        <p className="text-lg font-medium">No events to display</p>
        <p className="text-sm">Create an event to see it on the timeline</p>
      </div>
    );
  }

  return (
    <div className="relative py-8 overflow-y-auto">
      {/* Central timeline line */}
      <div className="absolute left-1/2 top-0 bottom-0 w-0.5 -translate-x-1/2 bg-border" />

      {/* Events */}
      <div className="relative space-y-6">
        {sortedEvents.map(({ event, side }, index) => (
          <div key={event.id}>
            {/* Insert current time marker at the right position */}
            {currentTime && index === currentTimePosition && (
              <div className="mb-6">
                <CurrentTimeMarker time={currentTime} />
              </div>
            )}

            <TimelineEvent
              event={event}
              side={side}
              onClick={() => onEventClick?.(event)}
            />
          </div>
        ))}

        {/* Current time marker at the end if all events are in the past */}
        {currentTime && currentTimePosition === sortedEvents.length && (
          <div className="mt-6">
            <CurrentTimeMarker time={currentTime} />
          </div>
        )}
      </div>

      {/* Timeline end cap */}
      <div className="absolute left-1/2 bottom-0 -translate-x-1/2">
        <div className="h-3 w-3 rounded-full bg-border" />
      </div>
    </div>
  );
}"}

